insert into product (id, name, subtitle, description, brand, category, price, stock) values (1, 'Sony WH-1000XM5', 'Bezprzewodowe słuchawki z redukcją hałasu', 'Nauszne słuchawki z jedną z najskuteczniejszych redukcji hałasu na rynku. Osiem mikrofonów wycisza szum samolotu, pociągu i open space, a rozmowy brzmią wyraźnie nawet na ulicy. Lekka konstrukcja pozwala nosić je przez cały dzień.', 'Sony', 'Słuchawki', 1299.00, 15);
