insert into product (id, name, subtitle, description, brand, category, price, stock) values (2, 'Bose QuietComfort Ultra', 'Flagowe słuchawki z dźwiękiem przestrzennym', 'Flagowe słuchawki Bose z dźwiękiem przestrzennym, który śledzi ruch głowy. Bardzo wygodne poduszki i mocna redukcja hałasu sprawdzają się w długich podróżach. Tryb świadomości pozwala słyszeć otoczenie bez zdejmowania słuchawek.', 'Bose', 'Słuchawki', 1899.00, 8);
