insert into product (id, name, subtitle, description, brand, category, price, stock) values (3, 'JBL Live 770NC', 'Słuchawki nauszne z adaptacyjnym ANC', 'Słuchawki nauszne z adaptacyjną redukcją hałasu i charakterystycznym, mocnym basem JBL. Bateria wystarcza na kilka tygodni dojazdów do pracy. Dobry wybór dla osób, które chcą ANC bez wydawania fortuny.', 'JBL', 'Słuchawki', 599.00, 20);
