insert into product (id, name, subtitle, description, brand, category, price, stock) values (4, 'Samsung Galaxy Buds3', 'Douszne słuchawki z ANC', 'Douszne słuchawki True Wireless z redukcją hałasu, zaprojektowane do współpracy z telefonami Galaxy. Automatycznie przełączają się między urządzeniami Samsung. Odporność IP57 pozwala używać ich w deszczu i na treningu.', 'Samsung', 'Słuchawki', 699.00, 0);
