insert into product (id, name, subtitle, description, brand, category, price, stock) values (5, 'JBL Flip 6', 'Przenośny głośnik wodoodporny', 'Poręczny głośnik Bluetooth w kształcie tuby, który zmieści się w bocznej kieszeni plecaka. Jest wodoodporny i pyłoszczelny, więc przetrwa plażę i deszcz. Dwa przetworniki dają zaskakująco głośny i czysty dźwięk.', 'JBL', 'Głośniki', 549.00, 25);
