insert into product (id, name, subtitle, description, brand, category, price, stock) values (6, 'Logitech MX Master 3S', 'Precyzyjna mysz do pracy', 'Ergonomiczna mysz biurowa z cichymi przyciskami i magnetycznym kółkiem, które przewija tysiące wierszy w sekundę. Działa na szkle i może sterować trzema komputerami naraz. Ulubiona mysz programistów i grafików.', 'Logitech', 'Myszy', 449.00, 30);
