insert into product (id, name, subtitle, description, brand, category, price, stock) values (17, 'JBL Endurance Peak 3', 'Sportowe słuchawki z zaczepami', 'Sportowe słuchawki z elastycznymi zaczepami, które nie wypadają podczas biegania. Są wodoodporne, więc pot i deszcz im nie szkodzą. Mocny bas motywuje na treningu.', 'JBL', 'Słuchawki', 399.00, 18);
