insert into product (id, name, subtitle, description, brand, category, price, stock) values (18, 'Shokz OpenRun Pro 2', 'Słuchawki z przewodnictwem kostnym do biegania', 'Słuchawki z przewodnictwem kostnym, które zostawiają uszy otwarte. Biegacz słyszy ruch uliczny i jednocześnie muzykę, co poprawia bezpieczeństwo. Lekka opaska praktycznie nie męczy podczas długich treningów.', 'Shokz', 'Słuchawki', 899.00, 7);
