insert into product (id, name, subtitle, description, brand, category, price, stock) values (19, 'Beats Powerbeats Pro 2', 'Słuchawki treningowe z pomiarem tętna', 'Słuchawki treningowe z zaczepami i wbudowanym pomiarem tętna. Działają zarówno z iPhone’em, jak i z Androidem. Redukcja hałasu pozwala skupić się na treningu na zatłoczonej siłowni.', 'Beats', 'Słuchawki', 1199.00, 5);
