insert into product (id, name, subtitle, description, brand, category, price, stock) values (20, 'HyperX Cloud III', 'Przewodowy headset dla graczy', 'Wygodny headset gamingowy z poduszkami z pianki memory i odłączanym mikrofonem. Dźwięk przestrzenny pomaga usłyszeć kroki przeciwników. Podłączysz go przez USB-C, USB-A lub jack 3,5 mm.', 'HyperX', 'Słuchawki', 449.00, 16);
