insert into product (id, name, subtitle, description, brand, category, price, stock) values (22, 'JBL Tune 520BT', 'Budżetowe słuchawki bezprzewodowe', 'Lekkie słuchawki nauszne w bardzo przystępnej cenie. Składają się na płasko, więc łatwo je zabrać na uczelnię. Bateria starcza na kilkadziesiąt godzin słuchania.', 'JBL', 'Słuchawki', 199.00, 35);
