insert into product (id, name, subtitle, description, brand, category, price, stock) values (23, 'JBL Charge 5', 'Głośnik z funkcją powerbanku', 'Wytrzymały głośnik Bluetooth, który przy okazji naładuje telefon. Gra głośno i z mocnym basem na grillu czy działce. Odporność IP67 oznacza, że przeżyje nawet kąpiel w basenie.', 'JBL', 'Głośniki', 749.00, 13);
