insert into product (id, name, subtitle, description, brand, category, price, stock) values (24, 'Sony ULT Field 1', 'Kompaktowy głośnik z trybem mocnego basu', 'Mały i wytrzymały głośnik z przyciskiem ULT, który podbija bas. Ma pasek do zawieszenia na plecaku lub rowerze. Jest odporny na wodę, kurz i upadki.', 'Sony', 'Głośniki', 499.00, 11);
